/** Build a minimal, valid placeholder CV PDF (proper xref offsets) */
function generateResumePdf(filePath) {
  const lines = [
    'ELENA VANCE — CURRICULUM VITAE',
    '',
    'Principal Product Designer & Systems Architect',
    'Brooklyn, NY & Remote — elena@elenavance.design',
    '',
    'Placeholder document generated by the Linen & Ultramarine studio.',
    'Replace via Studio > Resume once a signed PDF is available.',
  ];
  const content = `BT /F1 18 Tf 72 720 Td (${lines[0]}) Tj ET\nBT /F1 11 Tf 72 690 Td (${lines.slice(2).join(') Tj T* (')}) Tj ET`;
  const objects = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>',
    `<< /Length ${Buffer.byteLength(content)} >>\nstream\n${content}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  ];
  let pdf = '%PDF-1.4\n';
  const offsets = [];
  objects.forEach((body, i) => {
    offsets.push(Buffer.byteLength(pdf));
    pdf += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xrefStart = Buffer.byteLength(pdf);
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  pdf += offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('');
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;
  fs.writeFileSync(filePath, pdf, 'binary');
}

